import{_ as o,o as n,c as s,ag as r}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-10-24（神经科学 / 鸟类决策 / 知觉决策速度）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/neuroscience/science-daily-2026-10-24-neuro.md","filePath":"topics/neuroscience/science-daily-2026-10-24-neuro.md"}'),t={name:"topics/neuroscience/science-daily-2026-10-24-neuro.md"};function c(i,e,a,d,l,g){return n(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="科学日报-·-2026-10-24-神经科学-鸟类决策-知觉决策速度" tabindex="-1">科学日报 · 2026-10-24（神经科学 / 鸟类决策 / 知觉决策速度） <a class="header-anchor" href="#科学日报-·-2026-10-24-神经科学-鸟类决策-知觉决策速度" aria-label="Permalink to &quot;科学日报 · 2026-10-24（神经科学 / 鸟类决策 / 知觉决策速度）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-24.md</code> — 第43期 ｜ 科学板块（1 篇） 落盘说明：文件名带 <code>-neuro</code> 后缀以<strong>避免与其它主题同日同名文件互引产生伪边</strong>（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-24-乌鸦-235-毫秒做决定——比猴子和人快一倍-准确率却不减" tabindex="-1">科学日报 2026-10-24：乌鸦 235 毫秒做决定——比猴子和人快一倍，准确率却不减 <a class="header-anchor" href="#科学日报-2026-10-24-乌鸦-235-毫秒做决定——比猴子和人快一倍-准确率却不减" aria-label="Permalink to &quot;科学日报 2026-10-24：乌鸦 235 毫秒做决定——比猴子和人快一倍，准确率却不减&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-24.md</code> ｜ DOI: 10.1126/science.aed6459</p></blockquote><ul><li>问题：<strong>知觉决策（perceptual decision-making）在哺乳动物中被研究得很透</strong>，但其它脊椎动物（尤其鸟类）如何运作不清楚。</li><li>行为结果：<strong>小嘴乌鸦（Corvus corone）</strong> 在经典<strong>视觉运动辨别任务</strong>中做出「有意决策」，<strong>平均约 235 ms 报告选择</strong> —— <strong>约为猴子或人类已观测速度的两倍</strong>，且<strong>准确率不下降</strong>（速度-准确率权衡被打破）。</li><li>神经机制：记录<strong>端脑皮层（pallial endbrain）</strong> 显示—— <ul><li><strong>方向选择神经元</strong>早在<strong>刺激出现后约 70 ms</strong>（<strong>反应前约 170 ms</strong>）就已<strong>编码即将做出的选择</strong>；</li><li>其**「爬坡式」活动（ramping）随感觉证据强弱缩放**，并在<strong>反应起始时收敛</strong>。</li></ul></li><li>解释：鸟类决策回路<strong>效率极高</strong>，可能由<strong>快速视觉运动控制的演化压力</strong>塑造。</li><li>洞察（对本库 <code>neuroscience</code> × <code>ai-system-architecture</code>）：本条真正反常识的不是「鸟聪明」，而是**「速度不靠更大算力，而靠更早承诺（earlier commitment）」** —— 神经元<strong>在证据尚未累积完（70 ms，反应前 170 ms）就已经把选择写出来了</strong>，随后爬坡只是「加深」，不是「改判」。对照库内 10-20「听觉皮层 L5 树突编码抽象规则、胞体编码感觉刺激」（<strong>功能按『层』分工</strong>），本条给出一条<strong>按『时间』分工</strong>的判据：<strong>「早」的单元负责决定，「晚」的单元负责加深</strong>。迁移到 AI/外脑：<strong>推理延迟的优化点往往不在『算得更快』，而在『更早锁定假设，之后只做验证』</strong> —— 这与 10-23 Direct Pass@k 剪枝（<strong>尽早砍掉候选</strong>）、10-24 RLVR 轨迹（<strong>先升后降</strong>）在结构上同源：<strong>早期承诺 + 后续收敛，比全程最优化更高效。</strong></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/neuroscience/index.md</code> ｜ 第43期 科学板块</p></blockquote><p>关键词：小嘴乌鸦、Corvus corone、知觉决策、视觉运动辨别、235 毫秒、两倍快且不损准确率、速度-准确率权衡被打破、端脑皮层 pallial endbrain、方向选择神经元、刺激后 70ms 编码选择、反应前 170ms、爬坡活动随证据缩放、反应起始收敛、快速视觉运动演化压力、早承诺后加深、按时间分工、更早锁定假设</p><p>关联：<code>topics/neuroscience/science-daily-2026-10-22-neuro.md</code>、<code>topics/neuroscience/breathing-brain-decision.md</code>、<code>topics/neuroscience/science-daily-2026-10-20.md</code>、<code>topics/ai-system-architecture/science-daily-2026-10-24-ai.md</code>、<code>topics/neuroscience/index.md</code></p>',10)])])}const m=o(t,[["render",c]]);export{p as __pageData,m as default};
